import { Row, Col } from 'antd'
import get from 'lodash/get'
import { useCallback } from 'react'
import { formatMoney } from '../../../../../../../helpers/utility'
import { CalculationsStyle } from './index.style'

export default function Calculations (props) {
  const { reviewData, policyDetail } = props
  let discount = policyDetail.discount
  if (reviewData?.discount !== undefined) {
    discount = reviewData?.discount
  }

  const renderKeyVal = useCallback((key, val, isHeading = false) => {
    return (
      <Row type='flex' justify='space-between'>
        <Col className={isHeading ? 'bold' : ''}>
          {key}
        </Col>
        <Col className={isHeading ? 'bold' : ''}>
          {val}
        </Col>
      </Row>
    )
  }, [])

  const getAdditionalCharges = useCallback(() => {
    if (get(reviewData, 'premium_action', '')) {
      let charges = get(reviewData, 'premium_delta', '')
      if (get(reviewData, 'premium_action', '') === 'deduction') {
        charges = -1 * charges
      }
      return charges
    } else {
      return 0
    }
  }, [reviewData])

  const getNetPremium = useCallback(() => {
    return (
      parseFloat(get(policyDetail, 'payment_detail.base_premium', '').replaceAll(',', '')) +
      parseFloat(getAdditionalCharges()) - parseFloat(discount) +
      parseFloat(get(policyDetail, 'payment_detail.add_ons_premium', '').replaceAll(',', '')) +
      parseFloat(get(policyDetail, 'payment_detail.stamp_duty', 0).replaceAll(',', '')) +
      parseFloat(get(policyDetail, 'payment_detail.admin_fee', 0).replaceAll(',', ''))
    )
  }, [policyDetail, getAdditionalCharges,
    discount
  ])

  const getTotalPremium = useCallback(() => {
    return (
      parseFloat(getNetPremium()) +
      parseFloat(get(reviewData, 'endorsement_fee', 0)) +
      parseFloat(get(policyDetail, 'payment_detail.total_endorsement_fee', 0).replaceAll(',', '')) +
      parseFloat(get(policyDetail, 'payment_detail.total_premium_delta', 0).replaceAll(',', ''))
    )
  }, [reviewData, getNetPremium, policyDetail])

  const getTotalDifference = useCallback(() => {
    const diff = parseFloat(get(policyDetail, 'payment_detail.total_payment', '').replaceAll(',', '')) - getTotalPremium()
    if (diff > 0) {
      return `${formatMoney(diff)} lower`
    } else {
      return `${formatMoney(-diff)} higher`
    }
  }, [getTotalPremium, policyDetail])

  return (
    <CalculationsStyle>
      <h2> Calculations </h2>
      <div>
        {
          renderKeyVal(
            'Previous Total Payment',
            `Rp ${get(policyDetail, 'payment_detail.total_payment', '')}`,
            true
          )
        }
        <hr />
        <hr />
        {
          renderKeyVal(
            'Base Premium',
            `Rp ${get(policyDetail, 'payment_detail.base_premium', '')}`
          )
        }
        <hr />
        {
          renderKeyVal(
            'Addons Premium',
            `Rp ${get(policyDetail, 'payment_detail.add_ons_premium', '')}`
          )
        }
        <hr />
        {
          renderKeyVal(
            'Stamp Duty',
            `Rp ${get(policyDetail, 'payment_detail.stamp_duty', '')}`
          )
        }
        <hr />
        {
          renderKeyVal(
            'Admin Fee',
            `Rp ${get(policyDetail, 'payment_detail.admin_fee', '')}`
          )
        }
        <hr />
        {
          renderKeyVal(
            'Additional Coverage Changes',
            formatMoney(getAdditionalCharges())
          )
        }
        <hr />
        {
          renderKeyVal(
            'Discount',
            formatMoney(-discount)
          )
        }
        <hr />
        <hr />
        {
          renderKeyVal(
            'Net Premium',
            formatMoney(getNetPremium()), true
          )
        }
        <hr />
        {
          renderKeyVal(
            'Endorsement Fee',
            formatMoney(get(reviewData, 'endorsement_fee', 0))
          )
        }
        <hr />
        {
          renderKeyVal(
            'Previous Endorsements Fee',
            `Rp ${get(policyDetail, 'payment_detail.total_endorsement_fee', '0')}`
          )
        }
        <hr />
        {
          renderKeyVal(
            'Previous Premium Changes',
            `Rp ${get(policyDetail, 'payment_detail.total_premium_delta', '0')}`
          )
        }
        <hr />
        <hr />
        {
          renderKeyVal(
            'New Total Payment',
            formatMoney(getTotalPremium()),
            true
          )
        }
        <p>
          New Total Payment is {getTotalDifference()} than the original total payment
        </p>
      </div>

    </CalculationsStyle>
  )
}
