import { Row, Col } from 'antd'
import moment from 'moment'
import { useCallback } from 'react'

function CustomerInfo (props) {
  const {
    renderFormItems, isKeyDisabled,
    isPreview, customerInfo = [], reviewData = {},
    isDetail
  } = props

  const renderCustomerInfo = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        {
          customerInfo.map((attribute, i) => {
            return (
              <Col span={12} key={i}>
                {
                  renderFormItems({
                    name: attribute.data_key,
                    title: attribute.title,
                    subTitle: attribute.sub_title,
                    disabled: isKeyDisabled(attribute.data_key),
                    type: attribute.type,
                    defaultValue: attribute.type === 'date' ? moment(attribute.default_value, 'YYYY-MM-DD').format('DD-MM-YYYY') : attribute.default_value,
                    isEnableType: true,
                    runtimeRequestParams: attribute.runtime_request_params,
                    data: attribute.data
                  })
                }
              </Col>
            )
          })
        }
      </Row>
    )
  }, [customerInfo, renderFormItems,
    isKeyDisabled
  ])

  const renderPreviewCustomerInfo = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        {
          customerInfo
            .filter(
              (custInfo) => !!reviewData[custInfo.data_key])
            .map((custInfo, index) => (
              <Col
                key={`formData_${index}`}
                className='form-col-width field-margin'
              >
                <h3>
                  {custInfo.title}
                </h3>
                <div>
                  {
                  custInfo.type === 'date'
                    ? moment(reviewData[custInfo.data_key]).format('DD/MM/YYYY')
                    : reviewData[custInfo.data_key]
                }
                </div>
              </Col>
            ))
        }
      </Row>
    )
  }, [customerInfo, reviewData])

  const renderDetailCustomerInfo = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        {
          customerInfo
            .map((custInfo, index) => (
              <Col
                key={`formData_${index}`}
                className='form-col-width field-margin'
              >
                <h3>
                  {custInfo.name}
                </h3>
                <div>
                  {
                  custInfo.value
                }
                </div>
              </Col>
            ))
        }
      </Row>
    )
  }, [customerInfo])

  return (
    <div>
      {
      isPreview
        ? <h2> Customer Information </h2>
        : <h3> Customer Information </h3>
    }
      {
        (isPreview || isDetail)
          ? isPreview
              ? renderPreviewCustomerInfo()
              : renderDetailCustomerInfo()
          : renderCustomerInfo()
      }
    </div>
  )
}

export default CustomerInfo
