import { Modal, notification } from 'antd'
import React, { Component } from 'react'
import LayoutContentStyle from '../../../../../components/utility/layoutContent'
import EndorsementForm from './components/EndorsementForm'
import EndorsementFormReview from './components/EndorsementFormReview'
import { PolicyEndorsementStyle } from './index.style'
import agentAction from '../../../../redux/agent/actions'
import { connect } from 'react-redux'
import get from 'lodash/get'

import moment from 'moment'
import CircularLoader from '../../../../../components/CircularLoader'

const {
  getAgentInsuranceData, getEndorsementForm,
  createEndorsementForm, resetAgentRedux
} = agentAction

class PolicyEndorsement extends Component {
  constructor (props) {
    super(props)
    this.state = {
      showPreview: false,
      endorsementFormData: [],
      customerInfo: '',
      others: '',
      disableSubmitBtn: false
    }
    this.policyId = this.props.match.params.policy_id
  }

  handleSubmit = () => {
    this.setState({
      disableSubmitBtn: true
    })
    const finalData = {
      data: {}
    }
    const { endorsementFormData, customerInfo, others } = this.state
    Object.keys(endorsementFormData).forEach((key) => {
      let val = ''
      if (moment.isMoment(endorsementFormData[key])) { // handling date objects
        val = endorsementFormData[key].format('YYYY-MM-DD')
      } else {
        val = endorsementFormData[key]
      }
      finalData[key] = val
    })

    // this is just to send the data in backend required format
    customerInfo.forEach((cust) => {
      if (finalData[cust.data_key] || (finalData[cust.data_key] === 0)) {
        finalData.data[cust.data_key] = {
          value: finalData[cust.data_key]
        }
        if (cust.type === 'hybrid_radio') {
          finalData.data[cust.data_key][cust.radio_data_key] = finalData[cust.radio_data_key]
        }
        if (cust.type === 'search') {
          finalData.data[cust.data_key][cust.name_data_key] = finalData[cust.name_data_key]
        }
      }
    })

    others.forEach((oth) => {
      if (finalData[oth.data_key] || (finalData[oth.data_key] === 0)) {
        finalData.data[oth.data_key] = {
          value: finalData[oth.data_key]
        }
        if (oth.type === 'hybrid_radio') {
          finalData.data[oth.data_key][oth.radio_data_key] = finalData[oth.radio_data_key]
        }
        if (oth.type === 'search') {
          finalData.data[oth.data_key][oth.name_data_key] = finalData[oth.name_data_key]
        }
      }
    })
    this.props.createEndorsementForm({
      ...finalData,
      policyId: this.policyId
    })
  }

  componentDidUpdate () {
    const {
      endorsementFormError, endorsementMessage,
      endorsementForm, createEndorsementFormError, createEndorsementMessage,
      resetAgentRedux, history
    } = this.props

    if (endorsementMessage === 'success') {
      this.setState({
        customerInfo: get(endorsementForm, 'Customer Information', []),
        others: get(endorsementForm, 'Others', [])
      })
      resetAgentRedux(['endorsementMessage'])
    } else if (endorsementMessage && endorsementFormError) {
      notification.error({ message: endorsementMessage })
      resetAgentRedux(['endorsementMessage'])
    }

    if (createEndorsementMessage === 'success') {
      this.setState({
        disableSubmitBtn: false
      })
      history.push(`/agent/policy/${this.policyId}`)
      resetAgentRedux(['createEndorsementMessage'])
    } else if (createEndorsementMessage && createEndorsementFormError) {
      this.setState({
        disableSubmitBtn: false
      })
      notification.error({ message: createEndorsementMessage })
      resetAgentRedux(['createEndorsementMessage'])
    }
  }

  componentDidMount () {
    this.props.getAgentInsuranceData({ policyId: this.policyId })
    this.props.getEndorsementForm({ policyId: this.policyId })
  }

  handleShowPreview = (data) => {
    this.setState({
      endorsementFormData: { ...data },
      showPreview: !this.state.showPreview
    })
  }

  handleCancel = () => {
    this.setState({
      showPreview: false
    })
  }

  render () {
    const {
      showPreview, endorsementFormData,
      customerInfo, others, disableSubmitBtn
    } = this.state

    const {
      agentPolicy, getPolicyDetailLoader,
      endorsementFormLoader, createEndorsementFormLoader
    } = this.props

    return (
      <CircularLoader
        isSpining={
          getPolicyDetailLoader || endorsementFormLoader ||
          createEndorsementFormLoader
        }
      >
        <PolicyEndorsementStyle>
          <LayoutContentStyle>
            <p>Endorsement</p>
            {
              customerInfo && others &&
                <EndorsementForm
                  policyDetail={agentPolicy}
                  onShowPreview={this.handleShowPreview}
                  customerInfo={customerInfo}
                  others={others}
                  policyId={this.policyId}
                />
            }
            <Modal
              width='100vw'
              style={{ top: 0 }}
              visible={showPreview}
              title='Endorsment'
              footer={null}
              onCancel={this.handleCancel}
            >
              <EndorsementFormReview
                disableSubmitBtn={disableSubmitBtn}
                reviewData={endorsementFormData}
                customerInfo={customerInfo}
                others={others}
                policyDetail={agentPolicy}
                onSubmitForm={this.handleSubmit}
                onHideModal={this.handleCancel}
              />
            </Modal>

          </LayoutContentStyle>
        </PolicyEndorsementStyle>
      </CircularLoader>
    )
  }
}

export default connect(state => ({
  agentPolicy: state.Agent.agentPolicy,
  agentPolicyMessage: state.Agent.agentPolicyMessage,
  getPolicyDetailsError: state.Error.GET_AGENT_INSURANCE_DATA,
  getPolicyDetailLoader: state.Loading.GET_AGENT_INSURANCE_DATA,
  endorsementFormLoader: state.Loading.GET_ENDORSEMENT_FORM,
  endorsementFormError: state.Error.GET_ENDORSEMENT_FORM,
  endorsementMessage: state.Agent.endorsementMessage,
  endorsementForm: state.Agent.endorsementForm,
  createEndorsementFormLoader: state.Loading.CREATE_ENDORSEMENT_FORM,
  createEndorsementFormError: state.Error.CREATE_ENDORSEMENT_FORM,
  createEndorsementMessage: state.Agent.createEndorsementMessage,
  createEndorsementForm: state.Agent.createEndorsementForm
}), {
  getAgentInsuranceData,
  getEndorsementForm,
  createEndorsementForm,
  resetAgentRedux
})(PolicyEndorsement)
