import { Row, Col } from 'antd'
import { useCallback } from 'react'

function Others (props) {
  const {
    renderFormItems, isKeyDisabled,
    others = []
  } = props

  const renderOthers = useCallback(() => {
    return (
      <Row type='flex' justify='start'>
        {
          others.map((attribute, i) => {
            return (
              <Col span={12} key={`other_${i}`}>
                {
                  renderFormItems({
                    name: attribute.data_key,
                    title: attribute.title,
                    subTitle: attribute.sub_title,
                    disabled: isKeyDisabled(attribute.data_key),
                    type: attribute.type,
                    defaultValue: attribute.default_value,
                    isEnableType: true,
                    runtimeRequestParams: attribute.runtime_request_params,
                    data: attribute.data,
                    radioDataKey: attribute.radio_data_key
                  })
                }
              </Col>
            )
          })
        }
      </Row>
    )
  }, [others, isKeyDisabled,
    renderFormItems
  ])

  return (
    <div>
      <h3> Others </h3>
      {
        renderOthers()
      }
    </div>
  )
}

export default Others
