import { Component } from 'react'
import { Form, Button, Row, Col, notification, Collapse, message } from 'antd'
import { connect } from 'react-redux'
import moment from 'moment'
import { PolicyEndorsementFormStyle } from './index.style'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../../constants'
import policyActions from '../../../../../../../redux/policy/actions'
import agentActions from '../../../../../../redux/agent/actions'
import getUrlExtension from '../../../../../../../helpers/getExtensionUrl'
import renderFormItemsUtil from '../../../../../../../helpers/renderFormItems'
import Dates from '../Dates'
import Attachments from '../Attachments'
import CustomerInfo from '../CustomerInfo'
import Others from '../Others'
import Fees from '../Fees'
import { find } from 'lodash'

const { uploadPolicyFile, resetReduxState: policyResetReduxState } = policyActions
const { runtimeUpdateEndorsementForm, resetAgentRedux } = agentActions

class EndorsementForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      endorsmentFile: '',
      enabledFields: [],
      customerInfo: this.props.customerInfo || [],
      others: this.props.others || []
    }
    this.currentUploadType = ''
  }

  componentDidUpdate () {
    // handle the component update
    const {
      policyResetReduxState, uploadPolicyFileStatus, uploadPolicyFileData,
      runtimeUpdateEndorsementMessage, runtimeUpdateEndorsementData,
      runtimeUpdateEndorsementError, resetAgentRedux
    } = this.props
    const { customerInfo, others } = this.state

    if (uploadPolicyFileStatus === 'success') {
      if (this.currentUploadType === 'endorsement_file') {
        this.setState({
          endorsmentFile: uploadPolicyFileData.url
        })
      }
      this.currentUploadType = ''
      // clear the policy store after successful upload documents
      policyResetReduxState(['uploadPolicyFileStatus', 'uploadPolicyFileData'])
    }

    if (runtimeUpdateEndorsementMessage === 'success') {
      const {
        target_key: targetKey, target_value: targetValue,
        target_attribute: targetAttribute
      } = runtimeUpdateEndorsementData
      if (targetAttribute === 'data') {
        // setting the value as empty as the options will change now
        this.props.form.setFieldsValue({
          [targetKey]: ''
        })
        if (find(customerInfo, { data_key: targetKey })) {
          this.setState({
            customerInfo: customerInfo.map((cust) => {
              if (cust.data_key === targetKey) {
                return {
                  ...cust,
                  data: targetValue
                }
              } else {
                return cust
              }
            })
          })
        } else if (find(others, { data_key: targetKey })) {
          this.setState({
            others: others.map((oth) => {
              if (oth.data_key === targetKey) {
                return {
                  ...oth,
                  data: targetValue
                }
              } else {
                return oth
              }
            })
          })
        }
      } else if (targetAttribute === 'sub_title') {
        if (find(customerInfo, { data_key: targetKey })) {
          this.setState({
            customerInfo: this.state.customerInfo.map((cust) => {
              if (cust.data_key === targetKey) {
                return {
                  ...cust,
                  sub_title: targetValue
                }
              } else {
                return cust
              }
            })
          })
        } else if (find(others, { data_key: targetKey })) {
          this.setState({
            others: this.state.others.map((oth) => {
              if (oth.data_key === targetKey) {
                return {
                  ...oth,
                  sub_title: targetValue
                }
              } else {
                return oth
              }
            })
          })
        }
      }
      resetAgentRedux(['runtimeUpdateEndorsementMessage'])
    } else if (runtimeUpdateEndorsementError && runtimeUpdateEndorsementMessage) {
      notification.error({ message: runtimeUpdateEndorsementMessage })
      resetAgentRedux(['runtimeUpdateEndorsementMessage'])
    }
  }

  handleInputChange = (value, name) => {
    return value
  }

  handleRemoveEndorsmentFile = () => {
    this.setState({
      endorsmentFile: ''
    })
  }

  handleSubmit = e => {
    e.preventDefault()
    const { customerInfo, others } = this.state
    this.props.form.validateFields((err, values) => {
      if (!err) {
        let validationErr = false
        // checking manually if all the enabled fields have values
        this.state.enabledFields.forEach((field) => {
          if (values[field] !== 0 && !values[field]) {
            validationErr = true
            this.props.form.setFields({
              [field]: {
                errors: [new Error(`${field} is required!`)]
              }
            })
          }
        })
        if (validationErr) {
          return
        }

        const finalData = {
          ...values,
          endorsement_file_url: this.state.endorsmentFile
        }

        customerInfo.forEach((ck) => {
          if (this.isKeyDisabled(ck.data_key)) {
            delete finalData[ck.data_key]
            if (ck.type === 'hybrid_radio') {
              delete finalData[ck.radio_data_key]
            }
          } else if (ck.type === 'search') {
            finalData[ck.name_data_key] = document.getElementById(`${ck.data_key}_${finalData[ck.data_key]}`)?.innerHTML
          }
        })
        others.forEach((ok) => {
          if (this.isKeyDisabled(ok.data_key)) {
            delete finalData[ok.data_key]
            if (ok.type === 'hybrid_radio') {
              delete finalData[ok.radio_data_key]
            }
          } else if (ok.type === 'search') {
            finalData[ok.name_data_key] = document.getElementById(`${ok.data_key}_${finalData[ok.data_key]}`).innerHTML
          }
        })
        this.props.onShowPreview(finalData)
      }
    })
  }

  handleDisabledDate = (current, name) => {
    switch (name) {
      case 'request_date':
      case 'submission_date':
      case 'receive_date':
        return current > moment().endOf('day')
      default:
        break
    }
  }

  renderFormElementInRow = (formData = []) => {
    return (
      <Row type='flex' justify='start'>
        {
          formData.map((item, index) => (
            <Col
              key={`formData_${index}`}
              className={`form-col-width ${(index + 1) !== formData.length && 'field-margin'}`}
            >
              {this.renderFormItems(item)}
            </Col>
          ))
        }
      </Row>
    )
  }

  customRequest = ({ file }, name) => {
    this.currentUploadType = name
    const formData = new FormData()
    // we are sending this values for storage identification
    // can we upload any type of file like png, jpg, pdf
    if (file.name) {
      const fileName = file.name.split('.')[0]
      formData.append('file', file)
      formData.append('path', `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${Date.parse(new Date())}`)
      formData.append('identifier', 'agent')
      this.props.uploadPolicyFile({ body: formData })
    }
  }

  beforeUpload = (file, name) => {
    // file size validation for 10MB
    const isLt10M = file.size / 1024 / 1024 <= 10
    if (!isLt10M) {
      message.error('file must smaller than 10MB!')
    }
    return isLt10M
  }

  renderFormItems = (item) => {
    // wrapping utitily function with class function to pass common parameters
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: this.props.form.getFieldDecorator,
      getFieldValue: this.props.form.getFieldValue,
      handleRuntimeParams: this.handleRuntimeParams,
      handleInputChange: this.handleInputChange,
      handleDisabledDate: this.handleDisabledDate,
      customRequest: this.customRequest,
      handleChangeAttributeActive: this.handleChangeAttributeActive,
      isKeyDisabled: this.isKeyDisabled,
      beforeUpload: this.beforeUpload
    })
  }

  renderImgAndPdf = (url) => {
    const ext = getUrlExtension(url)
    if (ext === 'pdf') {
      return (
        <object
          type='application/pdf'
          data={url}
          width={150}
          height={150}
          aria-label='Policy Doc Pdf'
        />
      )
    }

    return <img width={150} src={url} alt='' />
  }

  handleChangeAttributeActive = (e, dataKey, radioDataKey = '') => {
    const { enabledFields } = this.state
    if (e.target.checked) {
      const newEnabledFields = [...enabledFields, dataKey]
      if (radioDataKey) {
        newEnabledFields.push(radioDataKey)
      }
      this.setState({
        enabledFields: newEnabledFields
      })
    } else {
      this.setState({
        enabledFields: enabledFields.filter((ef) => {
          if (ef === dataKey || ef === radioDataKey) {
            return false
          } else {
            return true
          }
        })
      }, () => {
        this.props.form.setFields({
          [dataKey]: {
            errors: false
          }
        })
        if (radioDataKey) {
          this.props.form.setFields({
            [radioDataKey]: {
              errors: false
            }
          })
        }
      })
    }
  }

  handleRuntimeParams = ({ name, value, runtimeRequestParams, handler = '' }) => {
    if (!value || !value.trim()) {
      return
    }
    const data = {}
    let isFieldEmpty = false

    runtimeRequestParams.forEach(key => {
      let val = this.props.form.getFieldValue(key)
      if ((key !== name) && (!val || !val.trim())) {
        isFieldEmpty = true
      } else {
        if (!isNaN(val)) {
          val = Number(parseFloat(val))
        }
        data[key] = val
      }
    })

    if (isFieldEmpty) {
      return
    }

    if (!isNaN(value)) {
      data[name] = Number(parseFloat(value))
    } else {
      data[name] = value
    }
    if (handler) {
      data.handler = handler
    } else {
      data.handler = name
    }

    this.props.runtimeUpdateEndorsementForm({
      ...data,
      policyId: this.props.policyId
    })
  }

  isKeyDisabled = (dataKey) => {
    const { enabledFields } = this.state
    return !enabledFields.includes(dataKey)
  }

  render () {
    return (
      <PolicyEndorsementFormStyle>
        <Form onSubmit={this.handleSubmit}>
          <h2>Required Information</h2>
          <hr />
          <div>
            <Dates
              renderFormElementInRow={this.renderFormElementInRow}
            />
            <hr />
            <Attachments
              renderFormItems={this.renderFormItems}
              endorsmentFile={this.state.endorsmentFile}
              renderImgAndPdf={this.renderImgAndPdf}
              onRemoveEndorsmentFile={this.handleRemoveEndorsmentFile}
            />
            <hr />
            <Fees
              renderFormElementInRow={this.renderFormElementInRow}
            />
          </div>

          <Collapse defaultActiveKey={['1']}>
            <Collapse.Panel header='Additional Options' key='1'>
              <div>
                <CustomerInfo
                  renderFormItems={this.renderFormItems}
                  customerInfo={this.state.customerInfo}
                  isKeyDisabled={this.isKeyDisabled}
                />
                <Others
                  renderFormItems={this.renderFormItems}
                  others={this.state.others}
                  isKeyDisabled={this.isKeyDisabled}
                />
              </div>
            </Collapse.Panel>
          </Collapse>
          <hr />
          <div>
            <Row type='flex' justify='space-between'>
              <Col span={12}>
                Policy endorsment document will be sent once you press the submit button.
                Make sure all the information you have filled are correct.
              </Col>
              <Col>
                <Form.Item>
                  <Button type='primary' htmlType='submit'>
                    Review
                  </Button>
                </Form.Item>
              </Col>
            </Row>
          </div>
        </Form>
      </PolicyEndorsementFormStyle>
    )
  }
}

const wrapperEndorsementForm = Form.create()(EndorsementForm)

export default connect(
  (state) => ({
    uploadPolicyFileLoading: state.Loading.UPLOAD_FILE,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData,
    runtimeUpdateEndorsementData: state.Agent.runtimeUpdateEndorsementData,
    runtimeUpdateEndorsementMessage: state.Agent.runtimeUpdateEndorsementMessage,
    runtimeUpdateEndorsementError: state.Error.RUNTIME_UPDATE_ENDORSEMENT_FORM,
    runtimeUpdateEndorsementLoader: state.Loading.RUNTIME_UPDATE_ENDORSEMENT_FORM
  }),
  {
    uploadPolicyFile,
    policyResetReduxState,
    runtimeUpdateEndorsementForm,
    resetAgentRedux
  }
)(wrapperEndorsementForm)
