import Attachments from '../Attachments'
import CustomerInfo from '../CustomerInfo'
import Dates from '../Dates'
import Calculations from '../Calculations'
import { Row, Col, Button, Icon } from 'antd'
import { EndorsementFormReviewStyle } from './index.style'
import { useCallback } from 'react'

function EndorsementFormReview (props) {
  const {
    reviewData, customerInfo,
    policyDetail, onSubmitForm,
    onHideModal
  } = props

  const checkIfCustInfoPresent = useCallback(() => {
    let showCustInfo = false
    customerInfo.forEach(custInfo => {
      if (reviewData[custInfo.data_key]) {
        showCustInfo = true
      }
    })
    return showCustInfo
  }, [reviewData, customerInfo])

  return (
    <EndorsementFormReviewStyle>
      <div className='back-to-edit' onClick={onHideModal}>
        <Icon type='arrow-left' /> Back to Editing
      </div>
      <hr />
      <Dates
        reviewData={reviewData}
        isPreview
      />
      <hr />
      <Attachments
        reviewData={reviewData}
        isPreview
      />
      <hr />
      {
        checkIfCustInfoPresent() &&
          <div>
            <CustomerInfo
              reviewData={reviewData}
              isPreview
              customerInfo={customerInfo}
            />
            <hr />
          </div>
      }

      <Calculations
        reviewData={reviewData}
        policyDetail={policyDetail}
      />
      <hr />
      <div>
        <Row type='flex' justify='space-between'>
          <Col span={12}>
            Policy endorsment document will be sent once you press the submit button.
            Make sure all the information you have filled are correct.
          </Col>
          <Col>
            <Button type='primary' onClick={onSubmitForm} disabled={props.disableSubmitBtn}>
              Submit
            </Button>
          </Col>
        </Row>
      </div>
    </EndorsementFormReviewStyle>
  )
}

export default EndorsementFormReview
